package com.mfg.mdm.service;
import com.mfg.common.api.ErrorCode;import com.mfg.common.exception.BizException;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.Date;import java.util.*;
@Service @RequiredArgsConstructor public class MdmGovernanceService{private final JdbcTemplate jdbc;
 @Transactional(readOnly=true)public Page<Map<String,Object>> page(String type,String keyword,String status,int page,int size){String table=table(type),code=columns(type)[0],name=columns(type)[1];int p=Math.max(0,page-1),s=Math.min(200,Math.max(1,size));List<Object>a=new ArrayList<>();StringBuilder w=new StringBuilder(" WHERE 1=1");if(keyword!=null&&!keyword.isBlank()){w.append(" AND (").append(code).append(" LIKE ? OR ").append(name).append(" LIKE ?)");a.add("%"+keyword+"%");a.add("%"+keyword+"%");}if(status!=null&&!status.isBlank()){w.append(" AND status=?");a.add(status);}Long total=jdbc.queryForObject("SELECT COUNT(*) FROM src_mdm."+table+w,Long.class,a.toArray());a.add(s);a.add(p*s);List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM src_mdm."+table+w+" ORDER BY id DESC LIMIT ? OFFSET ?",a.toArray());return new PageImpl<>(rows,PageRequest.of(p,s),total==null?0:total);}
 @Transactional public Map<String,Object> save(String type,Long id,Map<String,Object>x){int n;if(id==null){n=switch(type){case"warehouses"->jdbc.update("INSERT INTO src_mdm.md_warehouse(warehouse_code,warehouse_name,factory_code,warehouse_type) VALUES(?,?,?,?)",req(x,"warehouseCode"),req(x,"warehouseName"),req(x,"factoryCode"),text(x,"warehouseType"));case"work-centers"->jdbc.update("INSERT INTO src_mdm.md_work_center(work_center_code,work_center_name,workshop_code,capacity_per_day) VALUES(?,?,?,?)",req(x,"workCenterCode"),req(x,"workCenterName"),req(x,"workshopCode"),x.get("capacityPerDay"));case"production-versions"->{validateProduction(x);yield jdbc.update("INSERT INTO src_mdm.md_production_version(production_version_code,product_code,bom_code,bom_version,routing_code,routing_version,factory_code,effective_date,expire_date,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,'PUBLISHED',?)",req(x,"productionVersionCode"),req(x,"productCode"),req(x,"bomCode"),req(x,"bomVersion"),req(x,"routingCode"),req(x,"routingVersion"),req(x,"factoryCode"),Date.valueOf(String.valueOf(req(x,"effectiveDate"))),date(x,"expireDate"),CurrentUser.usernameOrSystem());}default->throw invalid();};id=((Number)jdbc.queryForMap("SELECT LAST_INSERT_ID() id").get("id")).longValue();}else{n=switch(type){case"warehouses"->jdbc.update("UPDATE src_mdm.md_warehouse SET warehouse_name=?,factory_code=?,warehouse_type=?,version_no=version_no+1 WHERE id=?",req(x,"warehouseName"),req(x,"factoryCode"),text(x,"warehouseType"),id);case"work-centers"->jdbc.update("UPDATE src_mdm.md_work_center SET work_center_name=?,workshop_code=?,capacity_per_day=?,version_no=version_no+1 WHERE id=?",req(x,"workCenterName"),req(x,"workshopCode"),x.get("capacityPerDay"),id);case"production-versions"->{validateProduction(x);yield jdbc.update("UPDATE src_mdm.md_production_version SET product_code=?,bom_code=?,bom_version=?,routing_code=?,routing_version=?,factory_code=?,effective_date=?,expire_date=?,version_no=version_no+1 WHERE id=? AND status='DRAFT'",req(x,"productCode"),req(x,"bomCode"),req(x,"bomVersion"),req(x,"routingCode"),req(x,"routingVersion"),req(x,"factoryCode"),Date.valueOf(String.valueOf(req(x,"effectiveDate"))),date(x,"expireDate"),id);}default->throw invalid();};}if(n==0)throw BizException.conflict("记录不存在或当前状态不可修改");return jdbc.queryForMap("SELECT * FROM src_mdm."+table(type)+" WHERE id=?",id);}
 @Transactional public void disable(String type,Long id){if(jdbc.update("UPDATE src_mdm."+table(type)+" SET status='DISABLED',version_no=version_no+1 WHERE id=?",id)==0)throw BizException.notFound("主数据",id);}
 @Transactional(readOnly=true)public List<Map<String,Object>> contacts(String partnerType,Long partnerId){return jdbc.queryForList("SELECT * FROM src_mdm.md_partner_contact WHERE partner_type=? AND partner_id=? ORDER BY is_primary DESC,id",partnerType,partnerId);}
 @Transactional public Map<String,Object> saveContact(String partnerType,Long partnerId,Long id,Map<String,Object>x){if(Boolean.TRUE.equals(x.get("primary")))jdbc.update("UPDATE src_mdm.md_partner_contact SET is_primary=0 WHERE partner_type=? AND partner_id=?",partnerType,partnerId);if(id==null){jdbc.update("INSERT INTO src_mdm.md_partner_contact(partner_type,partner_id,contact_name,position_name,mobile,email,is_primary) VALUES(?,?,?,?,?,?,?)",partnerType,partnerId,req(x,"contactName"),text(x,"positionName"),text(x,"mobile"),text(x,"email"),bool(x,"primary"));id=((Number)jdbc.queryForMap("SELECT LAST_INSERT_ID() id").get("id")).longValue();}else jdbc.update("UPDATE src_mdm.md_partner_contact SET contact_name=?,position_name=?,mobile=?,email=?,is_primary=? WHERE id=? AND partner_type=? AND partner_id=?",req(x,"contactName"),text(x,"positionName"),text(x,"mobile"),text(x,"email"),bool(x,"primary"),id,partnerType,partnerId);return jdbc.queryForMap("SELECT * FROM src_mdm.md_partner_contact WHERE id=?",id);}
 @Transactional public void deleteContact(String type,Long partnerId,Long id){jdbc.update("UPDATE src_mdm.md_partner_contact SET status='DISABLED' WHERE id=? AND partner_type=? AND partner_id=?",id,type,partnerId);}
 @Transactional public Map<String,Object> merge(Map<String,Object>x){String type=String.valueOf(req(x,"entityType")).toUpperCase(),table=switch(type){case"CUSTOMER"->"md_customer";case"SUPPLIER"->"md_supplier";case"MATERIAL"->"md_material";default->throw invalid();},code=switch(type){case"CUSTOMER"->"customer_code";case"SUPPLIER"->"supplier_code";default->"material_code";};Long survivor=Long.valueOf(String.valueOf(req(x,"survivorId"))),merged=Long.valueOf(String.valueOf(req(x,"mergedId")));if(survivor.equals(merged))throw BizException.conflict("保留记录与被合并记录不能相同");String survivorCode=String.valueOf(jdbc.queryForMap("SELECT "+code+" code FROM src_mdm."+table+" WHERE id=?",survivor).get("code")),mergedCode=String.valueOf(jdbc.queryForMap("SELECT "+code+" code FROM src_mdm."+table+" WHERE id=?",merged).get("code"));jdbc.update("UPDATE src_mdm."+table+" SET status='DISABLED',change_reason=? WHERE id=?", "合并至"+survivorCode,merged);jdbc.update("INSERT INTO src_mdm.md_merge_record(entity_type,survivor_id,merged_id,survivor_code,merged_code,reason,operator) VALUES(?,?,?,?,?,?,?)",type,survivor,merged,survivorCode,mergedCode,req(x,"reason"),CurrentUser.usernameOrSystem());jdbc.update("INSERT INTO src_mdm.md_code_mapping(entity_type,old_code,current_code) VALUES(?,?,?) ON DUPLICATE KEY UPDATE current_code=VALUES(current_code)",type,mergedCode,survivorCode);return jdbc.queryForMap("SELECT * FROM src_mdm.md_merge_record ORDER BY id DESC LIMIT 1");}
 @Transactional(readOnly=true)public Page<Map<String,Object>> governance(String kind,int page,int size){String table=switch(kind){case"merges"->"md_merge_record";case"mappings"->"md_code_mapping";case"history"->"md_change_history";default->throw invalid();};int p=Math.max(0,page-1),s=Math.min(200,Math.max(1,size));Long t=jdbc.queryForObject("SELECT COUNT(*) FROM src_mdm."+table,Long.class);return new PageImpl<>(jdbc.queryForList("SELECT * FROM src_mdm."+table+" ORDER BY id DESC LIMIT ? OFFSET ?",s,p*s),PageRequest.of(p,s),t==null?0:t);}
 private void validateProduction(Map<String,Object>x){String product=String.valueOf(req(x,"productCode")),bom=String.valueOf(req(x,"bomCode")),bv=String.valueOf(req(x,"bomVersion")),routing=String.valueOf(req(x,"routingCode")),rv=String.valueOf(req(x,"routingVersion"));if(count("md_product","product_code",product,"status IN ('PUBLISHED','CHANGING')")==0||count2("md_bom","bom_code",bom,"bom_version",bv,"status IN ('PUBLISHED','CHANGING')")==0||count2("md_routing","routing_code",routing,"routing_version",rv,"status IN ('PUBLISHED','CHANGING')")==0)throw BizException.of(ErrorCode.MASTER_DATA_NOT_PUBLISHED,"产品、BOM和工艺路线必须全部已发布");}
 private int count(String t,String c,Object v,String extra){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM src_mdm."+t+" WHERE "+c+"=? AND "+extra,Integer.class,v);return n==null?0:n;}private int count2(String t,String c,Object v,String c2,Object v2,String extra){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM src_mdm."+t+" WHERE "+c+"=? AND "+c2+"=? AND "+extra,Integer.class,v,v2);return n==null?0:n;}
 private String table(String t){return switch(t){case"warehouses"->"md_warehouse";case"work-centers"->"md_work_center";case"production-versions"->"md_production_version";default->throw invalid();};}private String[]columns(String t){return switch(t){case"warehouses"->new String[]{"warehouse_code","warehouse_name"};case"work-centers"->new String[]{"work_center_code","work_center_name"};case"production-versions"->new String[]{"production_version_code","product_code"};default->throw invalid();};}private BizException invalid(){return BizException.of(ErrorCode.PARAM_INVALID,"不支持的数据类型");}private Object req(Map<String,Object>x,String k){Object v=x.get(k);if(v==null||String.valueOf(v).isBlank())throw BizException.of(ErrorCode.PARAM_INVALID,k+"不能为空");return v;}private String text(Map<String,Object>x,String k){Object v=x.get(k);return v==null||String.valueOf(v).isBlank()?null:String.valueOf(v);}private Date date(Map<String,Object>x,String k){String v=text(x,k);return v==null?null:Date.valueOf(v);}private boolean bool(Map<String,Object>x,String k){return Boolean.parseBoolean(String.valueOf(x.getOrDefault(k,false)));}}
